// GET /api/v1/openapi.json (PRD 8.5, 8.2, D24): the OpenAPI 3.1 document of the API, generated by
// @hono/zod-openapi from the same route definitions that validate requests and responses, so the
// documented contract is the served one. Every route registered with api.openapi() is in it,
// including this one and /docs; the /api/docs redirect (./docs.ts) is not, being outside the base
// path.
//
// The document depends only on the code of a deploy, never on the bundle: no handler here calls the
// reader. It is generated on the first request, kept, and cached per deploy with a strong ETag of
// its bytes (./cache.ts).
import { createRoute, type RouteHandler, z } from '@hono/zod-openapi';

import {
  conditionalGet,
  deployCacheHeaders,
  deployCacheResponseHeaders,
  notModifiedResponse,
} from './cache.ts';
import { PROBLEM_MEDIA_TYPE, ProblemSchema } from './problem.ts';

export const OPENAPI_PATH = '/openapi.json';

/** The OpenAPI version of the document: 3.1.1 is the current 3.1 release (PRD 8.2). */
export const OPENAPI_VERSION = '3.1.1';

/**
 * The version of the API contract, independent of the bundle_version: a new bundle never changes
 * it. Its major version is the one in the base path (/api/v1). A new route or field, or a 501 that
 * becomes a record, raises the minor version; a change that breaks clients needs a new base path.
 */
export const API_VERSION = '1.0.0';

/**
 * The document info. Its text holds no number and no target, so it stays true for every bundle a
 * deploy may serve and makes no claim about results (PRD 3, 11).
 */
export const API_INFO = {
  title: 'Terraluna API',
  version: API_VERSION,
  description:
    'Read-only access to the Terraluna release bundle this deploy serves: its manifest, its ' +
    'validation gates and the records it holds. The API answers only GET and HEAD; every other ' +
    'method is refused, and there are no write endpoints. Responses follow the record schemas ' +
    'generated from the pipeline models, and errors are problem details ' +
    '(application/problem+json). A record the bundle does not hold is answered with a problem, ' +
    'never with a default or a computed value. A mock bundle is a placeholder: its manifest says ' +
    'mock is true, it holds no observations and no results, and a production deploy refuses to ' +
    'serve it.',
} as const;

/** The shape of the document as far as this route promises it; the rest is OpenAPI itself. */
const OpenApiDocumentSchema = z
  .looseObject({
    openapi: z
      .string()
      .regex(/^3\.1\.\d+$/)
      .openapi({ example: OPENAPI_VERSION }),
    info: z.looseObject({ title: z.string(), version: z.string() }),
    paths: z.record(z.string(), z.unknown()),
  })
  .openapi({ description: 'An OpenAPI 3.1 document.' });

export const openApiRoute = createRoute({
  method: 'get',
  path: OPENAPI_PATH,
  middleware: [conditionalGet],
  summary: 'This OpenAPI document',
  description:
    'The OpenAPI 3.1 document of this API, generated from the same route definitions that ' +
    'validate requests and responses. It depends on the deploy only, never on the bundle. ' +
    'Cached per deploy; the ETag is a hash of the bytes, and a matching If-None-Match is ' +
    'answered with 304.',
  responses: {
    200: {
      description: 'The OpenAPI document.',
      headers: deployCacheResponseHeaders(),
      content: { 'application/json': { schema: OpenApiDocumentSchema } },
    },
    304: notModifiedResponse,
    500: {
      description: 'The document could not be generated, or an unexpected error occurred.',
      content: { [PROBLEM_MEDIA_TYPE]: { schema: ProblemSchema } },
    },
  },
});

/**
 * The document handler over the app's document generator. The document is generated once, on the
 * first request, when every route is registered; a generator that throws is a 500 problem and is
 * tried again on the next request.
 */
export function openApiHandler(generate: () => object): RouteHandler<typeof openApiRoute> {
  let served: { body: string; headers: Record<string, string> } | undefined;
  return (c) => {
    if (served === undefined) {
      const body = JSON.stringify(generate());
      served = {
        body,
        headers: { 'Content-Type': 'application/json', ...deployCacheHeaders(body) },
      };
    }
    return c.body(served.body, 200, served.headers);
  };
}
